begin;create extension if not exists pgtap with schema extensions;select plan(20);
select has_table('public','discovery_sessions','sessions exist');select has_table('public','discovery_observations','observations exist');select has_table('public','discovery_intelligence','current intelligence exists');
select col_is_fk('public','discovery_sessions','organization_id','tenant provenance');select col_is_fk('public','discovery_sessions',array['candidate_id','organization_id'],'candidate provenance');select col_is_fk('public','discovery_sessions',array['consultant_membership_id','organization_id'],'consultant ownership');select col_is_fk('public','discovery_sessions',array['assessment_session_id','organization_id'],'assessment source');
select col_not_null('public','discovery_observations','source','observation provenance');select col_not_null('public','discovery_observations','status','finding status');select col_not_null('public','discovery_sessions','consultant_notes','private notes distinct');
select has_index('public','discovery_sessions','discovery_sessions_candidate_idx','multiple-session lookup');select has_index('public','discovery_intelligence','discovery_current_intelligence_idx','one current refinement');
select policies_are('public','discovery_sessions',array['discovery_sessions_access'],'session hierarchy policy');select policies_are('public','discovery_observations',array['discovery_observations_access'],'observation hierarchy policy');select policies_are('public','discovery_intelligence',array['discovery_intelligence_access'],'intelligence hierarchy policy');
select has_function('public','get_or_create_discovery_session',array['text'],'authorized creation/resume');select has_function('public','save_discovery_observation',array['text','text','text','text','text','discovery_finding_status','text','boolean'],'safe structured update');select has_function('public','save_discovery_notes',array['text','text','text','text'],'private notes boundary');select has_function('public','complete_discovery_session',array['text','jsonb','text'],'completion and readiness');select has_trigger('public','discovery_observations','discovery_observation_provenance','candidate and organization provenance immutable');
select*from finish();rollback;
